-- Queer Atlas: exactly four researched hotels for Canberra, Montpellier, Goa, Osaka and Cluj-Napoca.
-- Idempotent; all accommodation rows use the production-approved type 'hotel'.

begin;

alter table if exists public.places add column if not exists venue_intel jsonb not null default '{}'::jsonb;

with raw_hotels as (
 select * from jsonb_to_recordset($qa_hotels$
[
 {"name":"Ovolo Nishi","aliases":"Ovolo Nishi|Hotel Hotel Canberra|Ovolo Nishi Canberra","city":"canberra","description":"A cinematic NewActon hotel carved from recycled timber, rough stone and Australian art, where every corridor feels like a design exhibition and the city centre remains walkable.","vibe":"dramatic eco-design hotel with intimate queer-couple appeal","tags":"luxury,cultural,cozy","hours":"Reception operates 24 hours; Monster restaurant, gym and parking follow separate schedules.","link":"https://ovolohotels.com/ovolo/nishi/","location":"25 Edinburgh Avenue, Canberra ACT 2601, Australia","lat":-35.28529,"lng":149.12308,"arrival":"The sculptural building has varied room layouts; confirm accessible route, parking and natural-light preference.","best":"Best for design lovers wanting NewActon culture and a short trip to central queer nightlife.","crowd":"LGBTQ+ couples mix with architects, arts visitors, public servants and weekend city-break guests.","dress":"Creative city casual.","inclusion":"Current specialist guidance marks Ovolo Nishi as actively LGBTQ-friendly and welcoming to same-sex couples.","basis":"Current LGBTQ travel inclusion listing paired with active first-party hotel information.","class":"Luxury independent design hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.travelgay.com/gay-canberra-hotels","https://ovolohotels.com/ovolo/nishi/ask/"]},
 {"name":"QT Canberra","aliases":"QT Canberra|QT Hotel Canberra","city":"canberra","description":"A playful political hotel where dark timber, campaign-trail wit and the buzzy Capitol Bar place guests inside Canberra's sharpest after-work theatre.","vibe":"cheeky political glamour with a lively social lobby","tags":"luxury,social,cultural","hours":"Reception operates 24 hours; bar, restaurant and parking use separate schedules.","link":"https://www.qthotels.com/canberra/","location":"1 London Circuit, Canberra ACT 2601, Australia","lat":-35.28374,"lng":149.12555,"arrival":"Government functions and events pressure parking and lifts; reserve adapted rooms directly.","best":"Best for travellers who want central bars, political design and an energetic pre-nightlife base.","crowd":"LGBTQ+ visitors mix with political, media, wedding and corporate guests.","dress":"Polished playful smart-casual.","inclusion":"EVT/QT maintains diversity and inclusion commitments; property selection is reinforced by central access to Canberra's queer programme.","basis":"Active first-party property evidence and current corporate inclusion framework; no queer ownership claim.","class":"Upscale QT lifestyle hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.qthotels.com/canberra/","https://cdn.qthotels.com/wp-content/uploads/sites/95/2026/02/16151443/QTC_CEKit_2026-1-1.pdf"]},
 {"name":"Midnight Hotel, Autograph Collection","aliases":"Midnight Hotel, Autograph Collection|Midnight Hotel Canberra|Midnight Hotel","city":"canberra","description":"A darkly polished Braddon hotel with indoor pool, sauna and a central courtyard, placing guests beside Lonsdale Street and the rainbow roundabout.","vibe":"moody urban luxury in Canberra's most visibly queer-friendly neighbourhood","tags":"luxury,relax,social","hours":"Reception operates 24 hours; pool, sauna, restaurant and parking vary.","link":"https://www.marriott.com/en-us/hotels/cbrak-midnight-hotel-autograph-collection/overview/","location":"1 Elouera Street, Braddon ACT 2612, Australia","lat":-35.27375,"lng":149.13236,"arrival":"Weekend Braddon traffic and underground parking create peaks; confirm adapted room and pool access.","best":"Best for couples combining Braddon food, the rainbow roundabout and restorative pool time.","crowd":"Queer couples and Pride visitors mix with design travellers and government guests.","dress":"Contemporary city casual.","inclusion":"Marriott publishes LGBTQ+ inclusion commitments; location adds practical value without implying queer ownership.","basis":"Current corporate inclusion policy plus active first-party hotel and neighbourhood evidence.","class":"Luxury Autograph Collection hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.marriott.com/en-us/culture-and-values/diversity-and-inclusion.mi","https://www.marriott.com/en-us/hotels/cbrak-midnight-hotel-autograph-collection/overview/"]},
 {"name":"Hyatt Hotel Canberra - A Park Hyatt Hotel","aliases":"Hyatt Hotel Canberra - A Park Hyatt Hotel|Hyatt Hotel Canberra|Park Hyatt Canberra","city":"canberra","description":"Heritage-listed garden hotel near Parliament House with gracious lounges, indoor pool and art-deco calm—a stately counterweight to the city's compact club scene.","vibe":"historic diplomatic luxury with quiet couple-friendly public rooms","tags":"luxury,cultural,relax","hours":"Reception operates 24 hours; pool, high tea and dining have separate schedules.","link":"https://www.hyatt.com/hyatt-hotels-and-resorts/en-US/canbe-hyatt-hotel-canberra","location":"120 Commonwealth Avenue, Canberra ACT 2600, Australia","lat":-35.29946,"lng":149.12548,"arrival":"Official functions can affect security and driveway access; request room accessibility and transport in advance.","best":"Best for architecture, museums and couples preferring calm over a party lobby.","crowd":"LGBTQ+ couples mix with diplomatic, government, heritage and leisure guests.","dress":"Smart-casual; high tea and formal functions may elevate dress.","inclusion":"Hyatt maintains explicit LGBTQ+ inclusion commitments across guests and colleagues.","basis":"Current Hyatt inclusion policy and active first-party property source.","class":"Five-star heritage Park Hyatt-style hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.hyatt.com/world-of-care/diversity-equity-inclusion","https://www.hyatt.com/hyatt-hotels-and-resorts/en-US/canbe-hyatt-hotel-canberra"]},

 {"name":"Pullman La Pléiade Montpellier Centre","aliases":"Pullman La Pléiade Montpellier Centre|Pullman Montpellier Centre|Pullman Montpellier","city":"montpellier","description":"A sleek central hotel with rooftop pool and panoramic terrace, balancing Comédie access with a genuine retreat above the summer streets.","vibe":"rooftop urban resort minutes from Montpellier's queer circuit","tags":"luxury,relax,social","hours":"Reception operates 24 hours; rooftop pool, spa and restaurant are scheduled.","link":"https://all.accor.com/hotel/1294/index.en.shtml","location":"1 Rue des Pertuisanes, 34000 Montpellier, France","lat":43.60719,"lng":3.88518,"arrival":"Rooftop and summer demand require early spa, pool and adapted-room confirmation.","best":"Best for Pride visitors wanting the bars on foot and a pool above the city.","crowd":"LGBTQ+ couples and festival guests mix with business and leisure travellers.","dress":"Mediterranean smart-casual.","inclusion":"The official 2026 Montpellier press kit specifically lists Pullman among gay-friendly addresses.","basis":"Current destination authority LGBTQ listing plus active Accor property source.","class":"Upscale full-service Pullman hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.presseotc3m-montpelliermediterranee.fr/wp-content/uploads/2026/03/Dossier-de-Prensa-2026.pdf","https://all.accor.com/hotel/1294/index.en.shtml"]},
 {"name":"Hôtel Oceania Le Métropole Montpellier","aliases":"Hôtel Oceania Le Métropole Montpellier|Oceania Le Métropole Montpellier|Hotel Oceania Montpellier","city":"montpellier","description":"A Belle Époque landmark with glass-roofed restaurant, hidden summer garden and pool, only two minutes from the station and Comédie.","vibe":"grand historic hotel hiding a lush garden behind the city façade","tags":"luxury,cultural,relax","hours":"Reception operates 24 hours; pool, restaurant and garden service vary seasonally.","link":"https://www.oceaniahotels.com/en/oceania-le-metropole-montpellier","location":"3 Rue du Clos René, 34000 Montpellier, France","lat":43.60558,"lng":3.87968,"arrival":"Station traffic and historic layout require parking and adapted-room planning.","best":"Best for rail arrivals, garden downtime and walking to Saint-Roch gay bars.","crowd":"Queer couples and Pride visitors mix with heritage, conference and leisure guests.","dress":"Relaxed elegant city wear.","inclusion":"Named gay-friendly by Montpellier's official 2026 destination press material.","basis":"Direct current tourism authority inclusion plus active first-party hotel source.","class":"Four-star Belle Époque city hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.presseotc3m-montpelliermediterranee.fr/wp-content/uploads/2026/03/Dossier-de-Prensa-2026.pdf","https://www.oceaniahotels.com/en/oceania-le-metropole-montpellier"]},
 {"name":"Mercure Montpellier Centre Comédie","aliases":"Mercure Montpellier Centre Comédie|Mercure Montpellier Centre","city":"montpellier","description":"A practical full-service base near Antigone and Comédie, useful for travellers who want central queer nightlife without boutique-hotel pricing.","vibe":"reliable central hotel built for uncomplicated Pride weekends","tags":"mixed,cultural,social","hours":"Reception operates 24 hours; breakfast, restaurant and parking have separate hours.","link":"https://all.accor.com/hotel/3043/index.en.shtml","location":"6 Rue de la Spirale, 34000 Montpellier, France","lat":43.60745,"lng":3.88462,"arrival":"Tram, mall and event traffic complicate vehicle access; confirm garage and accessible rooms.","best":"Best for practical walking access to Pride, Comédie and the Écusson circuit.","crowd":"LGBTQ+ festival guests mix with business travellers, groups and families.","dress":"General city-hotel casual.","inclusion":"Mercure is explicitly included in Montpellier Tourism's current gay-friendly accommodation list.","basis":"Official 2026 destination LGBTQ evidence plus active first-party Accor operation.","class":"Four-star Mercure city hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.presseotc3m-montpelliermediterranee.fr/wp-content/uploads/2026/03/Dossier-de-Prensa-2026.pdf","https://all.accor.com/hotel/3043/index.en.shtml"]},
 {"name":"Grand Hôtel du Midi Montpellier","aliases":"Grand Hôtel du Midi Montpellier|Grand Hôtel du Midi|Grand Hotel du Midi","city":"montpellier","description":"An operatic Art Nouveau hotel directly on Place de la Comédie, dressing compact rooms in theatrical colour with the old town at the door.","vibe":"theatrical heritage stay at the centre of Montpellier's public life","tags":"luxury,cultural,cozy","hours":"Reception operates 24 hours; breakfast and bar schedules vary.","link":"https://www.grandhoteldumidimontpellier.com/","location":"22 Boulevard Victor Hugo, 34000 Montpellier, France","lat":43.60742,"lng":3.87932,"arrival":"Pedestrian-zone access and event noise require luggage instructions and a quiet-room request.","best":"Best for travellers wanting maximum character and a near-zero commute to central bars.","crowd":"LGBTQ+ couples and cultural tourists mix with opera, rail and city-break guests.","dress":"Creative smart-casual.","inclusion":"Selected within the city's openly LGBTQ-friendly destination context and central verified hotel inventory; no queer ownership claim.","basis":"Active first-party property source and official destination context, with deliberately limited inclusion wording.","class":"Four-star Art Nouveau boutique hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.grandhoteldumidimontpellier.com/fr","https://www.montpellier-tourisme.fr/sejourner/nos-sejours/idees-sejours-et-week-ends/montpellier-destination-friendly/"]},

 {"name":"The LaLiT Golf & Spa Resort Goa","aliases":"The LaLiT Golf & Spa Resort Goa|The Lalit Goa|LaLiT Goa","city":"goa","description":"An 85-acre Rajbaga beachfront resort where suites, a links course, spa and tropical privacy meet India's most explicit major-hotel commitment to queer guests and employees.","vibe":"expansive South Goa sanctuary with unusually credible LGBTQ+ inclusion","tags":"luxury,relax,cultural","hours":"Reception operates 24 hours; golf, spa, pools and restaurants have separate schedules.","link":"https://www.thelalit.com/the-lalit-goa/","location":"Raj Baga, Canacona, Goa 403702, India","lat":14.99691,"lng":74.04056,"arrival":"The remote South Goa position makes transfers essential; confirm couple treatment, accessibility and monsoon operation.","best":"Best for queer couples prioritising privacy, direct inclusion and resort-scale downtime over North Goa nightlife.","crowd":"LGBTQIA+ couples and families mix with luxury, wedding, golf and wellness guests.","dress":"Resort casual; restaurants may lean smart-casual.","inclusion":"LaLiT explicitly welcomes guests regardless of gender or sexual orientation, employs LGBTQIA+ people and markets this Goa resort directly to queer travellers.","basis":"Direct first-party hotel and group inclusion evidence, not a generic directory label.","class":"Five-star all-suite beachfront golf resort","coords":"Exact official address checked 2026-08-28.","sources":["https://blog.thelalit.com/blog/goa-lgbtq-gay-friendly-hotel-lalit-golf-spa-resort","https://www.thelalit.com/we-care-thelalit/love-for-all","https://www.thelalit.com/the-lalit-goa/"]},
 {"name":"THE Park Calangute Goa","aliases":"THE Park Calangute Goa|The Park Calangute|The Park Hotel Calangute","city":"goa","description":"A compact white-on-white boutique hotel pressed against Calangute Beach, with open-air dining, poolside sunset bar and history as a Pride De Goa event partner.","vibe":"bohemian beachfront boutique stay connected to Goa's queer-event history","tags":"luxury,social,relax","hours":"Reception operates 24 hours; Love restaurant runs continuously and Peace bar has separate hours.","link":"https://www.theparkhotels.com/calangute/","location":"Lane Opposite Calangute Mall, Calangute, Goa 403516, India","lat":15.53514,"lng":73.76223,"arrival":"Beach traffic and compact scale pressure parking and rooms; confirm accessibility and event noise.","best":"Best for North Goa social life, beach sunsets and proximity to rotating queer events.","crowd":"LGBTQ+ couples and event guests mix with design, beach and domestic leisure travellers.","dress":"Bohemian beach chic.","inclusion":"The property hosted a Pride De Goa pre-party and belongs to a design-hotel group associated with inclusive nightlife.","basis":"Documented Pride partnership paired with active first-party property source.","class":"Luxury boutique beachfront hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.theparkhotels.com/calangute/","https://goa.gaypassport.com/en/outing/restaurants"]},
 {"name":"W Goa","aliases":"W Goa|W Hotel Goa","city":"goa","description":"A cliff-and-garden Vagator resort with dramatic pool decks, spa, beach access and DJ energy close to North Goa's rotating queer party belt.","vibe":"high-design resort theatre beside Vagator's nightlife ecosystem","tags":"luxury,social,relax","hours":"Reception operates 24 hours; pools, spa, restaurants and music programming vary.","link":"https://www.marriott.com/en-us/hotels/goiwh-w-goa/overview/","location":"Vagator Beach, Bardez, Goa 403509, India","lat":15.60232,"lng":73.73333,"arrival":"Festival traffic and steep resort paths require transfer, mobility and room-location planning.","best":"Best for groups balancing pool spectacle, spa recovery and nearby queer pop-ups.","crowd":"LGBTQ+ couples and international groups mix with DJs, luxury travellers and wedding guests.","dress":"Fashion-forward resort wear.","inclusion":"W/Marriott maintains explicit global LGBTQ+ inclusion commitments; no local queer ownership claim.","basis":"Current corporate inclusion policy and active first-party resort evidence, reinforced by location near queer-event venues.","class":"Five-star W lifestyle resort","coords":"Exact official address checked 2026-08-28.","sources":["https://www.marriott.com/en-us/culture-and-values/diversity-and-inclusion.mi","https://www.marriott.com/en-us/hotels/goiwh-w-goa/overview/"]},
 {"name":"Grand Hyatt Goa","aliases":"Grand Hyatt Goa|Grand Hyatt Bambolim Goa","city":"goa","description":"A 28-acre waterfront resort on Bambolim Bay where Indo-Portuguese architecture, tropical lawns, a vast pool and full spa create a private central-Goa refuge.","vibe":"grand bayfront resort for private couple time between North and South Goa","tags":"luxury,relax,mixed","hours":"Reception operates 24 hours; pool, spa, dining and transfers have separate schedules.","link":"https://www.hyatt.com/grand-hyatt/en-US/goagh-grand-hyatt-goa","location":"P.O. Goa University, Bambolim, Goa 403206, India","lat":15.45888,"lng":73.84408,"arrival":"The large estate and central-bay position require transfers; confirm adapted rooms and distance to resort facilities.","best":"Best for queer couples seeking discreet full-service relaxation with easier Panaji access than far-south resorts.","crowd":"LGBTQ+ couples mix with luxury, wellness, family and destination-wedding guests.","dress":"Contemporary resort casual.","inclusion":"Hyatt publishes explicit LGBTQ+ inclusion commitments across guest and colleague experience.","basis":"Current Hyatt inclusion framework and verified active first-party resort information; no queer ownership claim.","class":"Five-star Grand Hyatt waterfront resort","coords":"Exact official address checked 2026-08-28.","sources":["https://www.hyatt.com/world-of-care/diversity-equity-inclusion","https://www.hyatt.com/grand-hyatt/en-US/goagh-grand-hyatt-goa"]},

 {"name":"Swissôtel Nankai Osaka","aliases":"Swissôtel Nankai Osaka|Swissotel Nankai Osaka","city":"osaka","description":"A tower directly above Nankai Namba Station where sweeping city views, pool and NAMBAR10 meet Osaka's strongest audited LGBTQ+ hotel credentials.","vibe":"major Namba hotel combining frictionless transport and benchmark queer welcome","tags":"luxury,social,cultural","hours":"Reception operates 24 hours; pool, spa, restaurants and NAMBAR10 vary.","link":"https://swissotelnankaiosaka.com/","location":"5-1-60 Namba, Chuo Ward, Osaka 542-0076, Japan","lat":34.66305,"lng":135.50174,"arrival":"Station scale and multiple lifts require clear arrival and adapted-room instructions.","best":"Best for first-time queer visitors wanting airport access, Pride events and audited inclusion.","crowd":"LGBTQIA2S+ couples and groups mix with international, rail, business and luxury guests.","dress":"Polished city casual; NAMBAR10 becomes expressive for drag events.","inclusion":"OCTB-accredited, IGLTA-accredited, host of Asia's first IGLTA convention and active Pride-event producer.","basis":"Direct first-party audited accreditation and current 2026 Pride programming.","class":"Five-star Swissôtel transport-hub hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://swissotelnankaiosaka.com/swissotel-nankai-osaka/live-it-well-osaka/lgbtqia2s/","https://visitgayosaka.com/column/columns/pride-2026.html"]},
