 {"name":"Radisson Blu Hotel, Cluj","aliases":"Radisson Blu Hotel, Cluj|Radisson Blu Cluj","city":"cluj_napoca","description":"A crisp modern hotel beside Central Park and Cluj Arena, with Japanese dining and easy walking access to the old centre while remaining insulated from festival noise.","vibe":"polished park-side base for Pride and major cultural festivals","tags":"luxury,cultural,relax","hours":"Reception operates 24 hours; restaurants, gym and parking vary.","link":"https://www.radissonhotels.com/en-us/hotels/radisson-blu-cluj","location":"Aleea Stadionului 1, Cluj-Napoca 400375, Romania","lat":46.76820,"lng":23.57362,"arrival":"Arena and festival dates pressure parking; confirm adapted rooms and late transport.","best":"Best for Pride visitors wanting a high-standard hotel between the park and historic centre.","crowd":"LGBTQ+ couples and festival guests mix with sports, conference and international travellers.","dress":"Modern city casual.","inclusion":"Radisson publishes global diversity and LGBTQ+ workplace commitments; no local queer ownership claim.","basis":"Current corporate inclusion policy and active first-party hotel source.","class":"Five-star Radisson Blu city hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.radissonhotels.com/en-us/corporate/responsible-business/diversity-inclusion","https://www.radissonhotels.com/en-us/hotels/radisson-blu-cluj"]},
 {"name":"DoubleTree by Hilton Cluj - City Plaza","aliases":"DoubleTree by Hilton Cluj - City Plaza|DoubleTree Cluj City Plaza|City Plaza Cluj","city":"cluj_napoca","description":"A central full-service hotel with rooftop pool and broad city views, close enough to walk to Urania, Cinema Victoria and Pride-week venues.","vibe":"reliable central comfort crowned by a restorative rooftop pool","tags":"luxury,relax,cultural","hours":"Reception operates 24 hours; pool, spa, restaurant and parking vary.","link":"https://www.hilton.com/en/hotels/cljcpdi-doubletree-cluj-city-plaza/","location":"9-13 Sindicatelor Street, Cluj-Napoca 400029, Romania","lat":46.76935,"lng":23.58489,"arrival":"Festival weekends strain garage and elevators; confirm couple bedding and adapted room directly.","best":"Best for first-time visitors wanting central walking and familiar service.","crowd":"LGBTQ+ couples and Pride guests mix with conference, university and leisure travellers.","dress":"General smart-casual.","inclusion":"Hilton maintains explicit LGBTQ+ inclusion and welcoming-travel commitments.","basis":"Current corporate inclusion evidence plus active first-party property source.","class":"Upscale DoubleTree full-service hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://travel.hilton.com/en_us/articles/lgbtq-travel/","https://www.hilton.com/en/hotels/cljcpdi-doubletree-cluj-city-plaza/"]},
 {"name":"Hotel Platinia","aliases":"Hotel Platinia|Platinia Hotel Cluj","city":"cluj_napoca","description":"An all-suite hotel integrated with Platinia Shopping Center, offering generous space, terraces and useful western access for longer stays or festival decompression.","vibe":"spacious contemporary suites for private, independent city stays","tags":"luxury,relax,mixed","hours":"Reception operates 24 hours; breakfast, parking and mall services vary.","link":"https://hotelplatinia.ro/","location":"Calea Mănăștur 2-6, Cluj-Napoca 400372, Romania","lat":46.76285,"lng":23.57180,"arrival":"Mall access and traffic can confuse arrivals; request exact hotel entrance and adapted layout.","best":"Best for queer couples wanting extra room, privacy and easy taxi access rather than a party lobby.","crowd":"LGBTQ+ couples mix with business, family, medical and longer-stay guests.","dress":"Contemporary casual.","inclusion":"Included in current LGBTQ-welcoming Cluj accommodation catalogues; no queer ownership or Pride partnership claim.","basis":"Current specialist inclusion evidence paired with active first-party property details.","class":"Five-star all-suite independent hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.expedia.ca/Cluj-Napoca-Hotels-LGBT-Friendly-Hotel.0-0-d860-tLGBTFriendlyHotel.Travel-Guide-Filter-Hotels","https://hotelplatinia.ro/"]},
 {"name":"Hampton by Hilton Cluj-Napoca","aliases":"Hampton by Hilton Cluj-Napoca|Hampton Cluj-Napoca|Hampton Cluj","city":"cluj_napoca","description":"A practical east-centre hotel with breakfast included, gym and straightforward rooms, suited to Pride travellers who value predictable costs and a quieter sleep.","vibe":"uncomplicated inclusive base with useful central-east access","tags":"mixed,cozy,cultural","hours":"Reception operates 24 hours; breakfast, gym and parking follow property schedules.","link":"https://www.hilton.com/en/hotels/cljrohx-hampton-cluj-napoca/","location":"Bulevardul 21 Decembrie 1989 67, Cluj-Napoca 400124, Romania","lat":46.77548,"lng":23.60226,"arrival":"Business and festival dates pressure parking; confirm adapted room and taxi pickup.","best":"Best for value-conscious queer travellers who want breakfast included and reliable service.","crowd":"LGBTQ+ solo visitors and couples mix with business, family and short-stay guests.","dress":"Everyday casual.","inclusion":"Covered by Hilton's explicit LGBTQ+ travel and workplace inclusion commitments.","basis":"Current corporate inclusion evidence and active first-party property information.","class":"Midscale Hampton by Hilton hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://travel.hilton.com/en_us/articles/lgbtq-travel/","https://www.hilton.com/en/hotels/cljrohx-hampton-cluj-napoca/"]}
]
$qa_hotels$) h(name text,aliases text,city text,description text,vibe text,tags text,hours text,link text,location text,lat double precision,lng double precision,arrival text,best text,crowd text,dress text,inclusion text,basis text,class text,coords text,sources jsonb)
), hotels as (select h.*,string_to_array(h.tags,',')::text[] approved_tags,jsonb_build_object('queue_wait',arrival,'best_nights',best,'crowd_mix',crowd,'dress_code',dress,'staff_inclusivity',inclusion,'inclusion_basis',basis,'hotel_class',class,'coordinate_source',coords,'source_urls',sources,'research_status','current_inclusion_and_official_property_sources','updated_at','2026-08-28T00:00:00Z') intel from raw_hotels h), updated as (update public.places p set name=h.name,type='hotel',description=h.description,vibe=h.vibe,vibe_tags=h.approved_tags,hours=h.hours,link=h.link,location=h.location,lat=h.lat,lng=h.lng,venue_intel=coalesce(p.venue_intel,'{}'::jsonb)||h.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from hotels h where lower(trim(p.city))=h.city and lower(trim(p.name)) in(select lower(trim(alias_name)) from unnest(string_to_array(h.aliases,'|')) alias_name) returning p.id)
insert into public.places(name,city,type,description,vibe,vibe_tags,hours,link,location,lat,lng,venue_intel,seo_indexable,seo_quality_status,updated_at) select h.name,h.city,'hotel',h.description,h.vibe,h.approved_tags,h.hours,h.link,h.location,h.lat,h.lng,h.intel,true,'approved',timezone('utc',now()) from hotels h where not exists(select 1 from public.places p where lower(trim(p.city))=h.city and lower(trim(p.name)) in(select lower(trim(alias_name)) from unnest(string_to_array(h.aliases,'|')) alias_name));

select public.qa_refresh_city_seo_status(slug) from (values('canberra'),('montpellier'),('goa'),('osaka'),('cluj_napoca')) v(slug) where to_regprocedure('public.qa_refresh_city_seo_status(text)') is not null;

commit;

select lower(trim(city)) city,count(*) filter(where type='hotel') batch_hotel_count,count(*) filter(where type='hotel')=4 target_exactly_four
from public.places
where lower(trim(city)) in('canberra','montpellier','goa','osaka','cluj_napoca')
  and lower(trim(name)) in(
    'ovolo nishi','qt canberra','midnight hotel, autograph collection','hyatt hotel canberra - a park hyatt hotel',
    'pullman la pléiade montpellier centre','hôtel oceania le métropole montpellier','mercure montpellier centre comédie','grand hôtel du midi montpellier',
    'the lalit golf & spa resort goa','the park calangute goa','w goa','grand hyatt goa',
    'swissôtel nankai osaka','hotel the lutheran','intercontinental hotel osaka','the osaka station hotel, autograph collection',
    'radisson blu hotel, cluj','doubletree by hilton cluj - city plaza','hotel platinia','hampton by hilton cluj-napoca'
  )
group by lower(trim(city)) order by lower(trim(city));
